def as_of(examples, features, max_age=None):
    """examples: list of (entity, t). features: list of (entity, available_at, value).
    Return one value per example: the latest value for that entity with available_at <= t,
    or None if there is none (or, when max_age is given, if it is older than max_age)."""
    latest = {}
    for entity, available_at, value in features:
        if entity not in latest or available_at > latest[entity][0]:
            latest[entity] = (available_at, value)
    return [latest.get(entity, (None, None))[1] for entity, t in examples]

