from bisect import bisect_right
from collections import defaultdict

def as_of(examples, features, max_age=None):
    history = defaultdict(list)
    for entity, available_at, value in features:
        history[entity].append((available_at, value))
    for h in history.values():
        h.sort()
    times = {e: [a for a, _ in h] for e, h in history.items()}
    out = []
    for entity, t in examples:
        i = bisect_right(times.get(entity, []), t) - 1      # last value available at or before t
        if i < 0:
            out.append(None)
            continue
        available_at, value = history[entity][i]
        out.append(None if max_age is not None and t - available_at > max_age else value)
    return out

import re

def words(text):
    return re.findall(r"[^\W_]+", text.lower())

def ngrams(ws, n):
    return {tuple(ws[i:i + n]) for i in range(len(ws) - n + 1)}

def contaminated(train_docs, test_items, n=8):
    test_grams = set()
    for item in test_items:
        test_grams |= ngrams(words(item), n)
    return [i for i, doc in enumerate(train_docs) if ngrams(words(doc), n) & test_grams]

exercises.solution:
Build one set of test $n$-grams, then check each document against it:

```python
import re

def words(text):
    return re.findall(r"[^\W_]+", text.lower())

def ngrams(ws, n):
    return {tuple(ws[i:i + n]) for i in range(len(ws) - n + 1)}

def contaminated(train_docs, test_items, n=8):
    test_grams = set()
    for item in test_items:
        test_grams |= ngrams(words(item), n)
    return [i for i, doc in enumerate(train_docs) if ngrams(words(doc), n) & test_grams]
```

The tests show the method's character. The forum post that copies the maths question with different case and punctuation is caught, and so is a truncated copy (document 4). The quiz-night line that writes `Krakow` without the accent is *not* caught at $n = 8$: one changed word breaks every 8-gram that contains it, and only 7 words follow it. And with $n = 13$ the 12-word geography question can contaminate nothing, because it has no 13-grams at all — real decontamination code must handle items shorter than $n$, for example by matching the whole item. Long $n$ avoids false alarms on common phrases; short $n$ catches more paraphrases and flags more innocent text. No $n$-gram method catches translations or rewordings, which is why held-out and freshly written test sets matter.
